{"code": "
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def range_gcd(l, r, data, log_table, st):
    """Compute GCD of range [l, r] using sparse table"""
    length = r - l + 1
    k = log_table[length]
    return gcd(st[l][k], st[r - (1 << k) + 1][k])

n = int(input())
s = list(map(int, input().split()))
t = int(input())
queries = []

# Preprocess for range GCD using sparse table
log_table = [0] * (n + 1)
for i in range(2, n + 1):
    log_table[i] = log_table[i // 2] + 1

# Build sparse table
st = [[0] * (log_table[n] + 1) for _ in range(n)]
for i in range(n):
    st[i][0] = s[i]
for j in range(1, log_table[n] + 1):
    for i in range(n - (1 << j) + 1):
        st[i][j] = gcd(st[i][j - 1], st[i + (1 << (j - 1))][j - 1])

# Process queries
for _ in range(t):
    l, r = map(int, input().split())
    l -= 1  # Convert to 0-indexed
    r -= 1

    # Find GCD of the segment
    segment_gcd = range_gcd(l, r, s, log_table, st)

    # Count how many ants have this GCD value
    count = 0
    for i in range(l, r + 1):
        if s[i] == segment_gcd:
            count += 1

    # Number of ants eaten = total ants - count
    print((r - l + 1) - count)
