import sys

def solve():
    a, b, c = map(int, sys.stdin.readline().split())

    # Check if a solution is possible
    if (a + b - c) % 2 != 0:
        print("Impossible")
        return

    x = (a + b - c) // 2
    y = (b - a + c) // 2
    z = (a - b + c) // 2

    # Check if all values are non-negative
    if x >= 0 and y >= 0 and z >= 0:
        print(x, y, z)
    else:
        print("Impossible")

if __name__ == "__main__":
    solve()
