{"code": "
def count_almost_sorted(n):
    """Count the number of almost sorted permutations of length n."""
    if n == 0:
        return 1

    # The number of almost sorted permutations of length n is 2^(n-1)
    return 1 << (n - 1)


def find_kth_almost_sorted(n, k):
    """Find the k-th almost sorted permutation of length n in lexicographical order."""
    if k > count_almost_sorted(n):
        return -1

    # We'll build the permutation recursively
    result = []

    def dfs(pos, used):
        """Recursive DFS to build the permutation."""
        if pos == n:
            return True

        # Try each possible next element
        for i in range(1, n + 1):
            if not used[i]:
                # Check if this element can follow the last element in the permutation
                if pos == 0 or i >= result[-1] - 1:
                    result.append(i)
                    used[i] = True

                    # Count how many permutations start with this choice
                    # We need to count permutations starting with the current prefix
                    # We can do this by considering the remaining elements

                    # The number of permutations starting with a given prefix is 2^(remaining - 1)
                    remaining = n - pos - 1
                    count = 1 << remaining

                    if k <= count:
                        # This choice is valid, we keep it
                        return True
                    else:
                        # This choice is not valid, we backtrack
                        result.pop()
                        used[i] = False
                        k -= count

        return False

    dfs(0, [False] * (n + 1))
    return result


t = int(input())
for _ in range(t):
    n, k = map(int, input().split())
    result = find_kth_almost_sorted(n, k)
    if result == -1:
        print(-1)
    else:
        print(' '.join(map(str, result)) + ' ')
