def longest_path(start, visited, graph, memo):
    if start in visited:
        return 0

    visited.add(start)
    max_len = 1

    for neighbor in graph[start]:
        if neighbor not in visited:
            result = 1 + longest_path(neighbor, visited, graph, memo)
            max_len = max(max_len, result)

    visited.remove(start)
    memo[start] = max_len
    return max_len

