def bfs(dist, prev, graph, match_to, n, m):
    """BFS for Hopcroft-Karp algorithm"""
    queue = []
    for u in range(n):
        if match_to[u] == -1:
            dist[u] = 0
            queue.append(u)
        else:
            dist[u] = float('inf')
    dist_found = float('inf')
    while queue:
        u = queue.pop(0)
        if dist[u] < dist_found:
            for v in graph[u]:
                if dist[match_to[v]] == float('inf'):
                    dist[match_to[v]] = dist[u] + 1
                    prev[match_to[v]] = u
                    queue.append(match_to[v])
                    if dist[match_to[v]] == 1:
                        dist_found = dist[match_to[v]]
    return dist_found != float('inf')

def dfs(u, dist, prev, graph, match_to, n, m):
    """DFS for Hopcroft-Karp algorithm"""
    for v in graph[u]:
        if dist[match_to[v]] == dist[u] + 1:
            if dfs(match_to[v], dist, prev, graph, match_to, n, m):
                match_to[v] = u
                return True
    dist[u] = float('inf')
    return False

def hopcroft_karp(graph, n, m):
    """Hopcroft-Karp algorithm for maximum bipartite matching"""
    match_to = [-1] * m
    dist = [0] * n
    result = 0
    while bfs(dist, match_to, graph, match_to, n, m):
        prev = [-1] * m
        while True:
            if not dfs(0, dist, prev, graph, match_to, n, m):
                break
            result += 1
    return match_to

