def solve():
    n = int(input())
    points = []
    for _ in range(n):
        p, c = input().split()
        points.append((int(p), c))

    # Connect all green points with edges between consecutive green points
    green_edges = 0
    green_positions = []
    for p, c in points:
        if c == 'G':
            green_positions.append(p)
    for i in range(len(green_positions) - 1):
        green_edges += green_positions[i+1] - green_positions[i]

    # Connect all red points with edges between consecutive red points
    red_edges = 0
    red_positions = []
    for p, c in points:
        if c == 'R':
            red_positions.append(p)
    for i in range(len(red_positions) - 1):
        red_edges += red_positions[i+1] - red_positions[i]

    # Connect all blue points with edges between consecutive blue points
    blue_edges = 0
    blue_positions = []
    for p, c in points:
        if c == 'B':
            blue_positions.append(p)
    for i in range(len(blue_positions) - 1):
        blue_edges += blue_positions[i+1] - blue_positions[i]

    # Connect first green to first red (if any)
    if green_positions and red_positions:
        green_edges += abs(green_positions[0] - red_positions[0])

    # Connect first green to first blue (if any)
    if green_positions and blue_positions:
        green_edges += abs(green_positions[0] - blue_positions[0])

    total = green_edges + red_edges + blue_edges
    print(total)

solve()
