import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    # Dictionary to track current value at each position
    value_at = {}

    idx = 1
    for _ in range(n):
        a = int(data[idx])
        b = int(data[idx + 1])
        idx += 2

        # Swap values at positions a and b
        value_at[a], value_at[b] = value_at.get(b, b), value_at.get(a, a)

    # Count inversions
    inversions = 0

    # Check all pairs of positions that have been swapped
    swapped_positions = list(value_at.keys())
    for i in range(len(swapped_positions)):
        for j in range(i + 1, len(swapped_positions)):
            pos_i = swapped_positions[i]
            pos_j = swapped_positions[j]

            # Get values at these positions
            val_i = value_at[pos_i]
            val_j = value_at[pos_j]

            # If pos_i < pos_j and val_i > val_j, it's an inversion
            if pos_i < pos_j and val_i > val_j:
                inversions += 1

    # Also check pairs where one position has been swapped and the other hasn't
    for pos in swapped_positions:
        for other_pos in value_at:
            if other_pos < pos:
                # other_pos hasn't been swapped, so its value is other_pos
                if value_at[pos] > other_pos:
                    inversions += 1
            elif pos < other_pos:
                # other_pos hasn't been swapped, so its value is other_pos
                if other_pos > value_at[pos]:
                    inversions += 1

    print(inversions)

if __name__ == "__main__":
    solve()
