def can_achieve_sum(ingredients, protein, index, target):
    """Check if we can achieve the target sum using ingredients from index onwards"""
    # Use dynamic programming to check if we can achieve the target
    # dp[i][s] = True if we can achieve sum s using ingredients from index i onwards
    n = len(ingredients)
    dp = [[False] * (target + 1) for _ in range(n + 1)]
    dp[n][0] = True  # Base case: no ingredients left, sum 0 is achievable

    for i in range(n - 1, -1, -1):
        for s in range(target + 1):
            # Option 1: skip the i-th ingredient
            if dp[i + 1][s]:
                dp[i][s] = True
            # Option 2: take the i-th ingredient if possible
            if s >= protein[i] and dp[i + 1][s - protein[i]]:
                dp[i][s] = True

    return dp[index][target]

def find_lex_smallest_subsequence(ingredients, protein, target):
    """Find the lexicographically smallest subsequence that sums to target"""
    n = len(ingredients)

    # Use backtracking with memoization
    memo = {}

    def backtrack(index, remaining_sum, path):
        if index == n:
            if remaining_sum == 0:
                return path
            return None

        key = (index, remaining_sum)
        if key in memo:
            return memo[key]

        # Option 1: skip the current ingredient
        result = backtrack(index + 1, remaining_sum, path)

        # Option 2: take the current ingredient if possible
        if remaining_sum >= protein[index] and can_achieve_sum(ingredients, protein, index + 1, remaining_sum - protein[index]):
            new_path = path + ingredients[index]
            option2 = backtrack(index + 1, remaining_sum - protein[index], new_path)

            if option2 is not None:
                # Compare lexicographically
                if result is None or option2 < result:
                    result = option2

        memo[key] = result
        return result

    result = backtrack(0, target, "")
    return result if result is not None else "IMPOSSIBLE"

