import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    results = []

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        max_product = 0

        # Consider all subarrays of length 2
        for i in range(n - 1):
            product = a[i] * a[i + 1]
            if product > max_product:
                max_product = product

        results.append(str(max_product))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
