def find_suffixes(s):
    n = len(s)
    suffixes = set()

    # Try all possible root lengths (at least 5 letters)
    for root_len in range(5, n):
        # The remaining string after the root
        remaining = s[root_len:]

        # Try to split the remaining string into suffixes of length 2 or 3
        # with no two consecutive suffixes being the same

        # Use backtracking to find all valid suffixes
        def backtrack(start, last_suffix):
            # If we've reached the end, we're done
            if start == len(remaining):
                return

            # Try taking a suffix of length 2
            if start + 2 <= len(remaining):
                suffix = remaining[start:start+2]
                if suffix != last_suffix:
                    # Try this suffix and see if we can complete the construction
                    if backtrack(start + 2, suffix):
                        suffixes.add(suffix)

            # Try taking a suffix of length 3
            if start + 3 <= len(remaining):
                suffix = remaining[start:start+3]
                if suffix != last_suffix:
                    # Try this suffix and see if we can complete the construction
                    if backtrack(start + 3, suffix):
                        suffixes.add(suffix)

        # Start with no previous suffix
        if backtrack(0, ""):
            pass  # We just need to know if a valid construction exists

    return sorted(suffixes)

# Read input
s = input().strip()

# Find and print suffixes
suffixes = find_suffixes(s)
print(len(suffixes))
for suffix in suffixes:
    print(suffix)
