def max_overlap(a, b):
    """Calculate maximum overlap where suffix of a matches prefix of b"""
    max_len = 0
    for i in range(1, min(len(a), len(b)) + 1):
        if a[-i:] == b[:i]:
            max_len = i
    return max_len

def solve():
    while True:
        n = int(input())
        if n == 0:
            break

        cities = []
        for _ in range(n):
            cities.append(input().strip())

        # Calculate overlaps
        overlap = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    overlap[i][j] = max_overlap(cities[i], cities[j])

        # DP: dp[mask][i] = minimum length to include all cities in mask, ending with city i
        dp = [[float('inf')] * n for _ in range(1 << n)]

        # Initialize: only one city
        for i in range(n):
            dp[1 << i][i] = len(cities[i])

        # DP transition
        for mask in range(1 << n):
            for last in range(n):
                if not (mask & (1 << last)):
                    continue

                # Try to add another city
                for next_city in range(n):
                    if mask & (1 << next_city):
                        continue

                    # New mask
                    new_mask = mask | (1 << next_city)

                    # Length = current length + length of next city - overlap
                    dp[new_mask][next_city] = min(
                        dp[new_mask][next_city],
                        dp[mask][last] + len(cities[next_city]) - overlap[last][next_city]
                    )

        # Find minimum length
        result = min(dp[(1 << n) - 1][i] for i in range(n))
        print(result)

solve()
