class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.min_power = list(range(n + 1))

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        fx = self.find(x)
        fy = self.find(y)
        if fx != fy:
            self.parent[fy] = fx
            self.min_power[fx] = min(self.min_power[fx], self.min_power[fy])

    def get_min(self, x):
        return self.min_power[self.find(x)]

n, m = map(int, input().split())
uf = UnionFind(n)

# Track edges
edges = [[] for _ in range(n + 1)]
for _ in range(m):
    u, v = map(int, input().split())
    uf.union(u, v)
    edges[u].append(v)
    edges[v].append(u)

q = int(input())
for _ in range(q):
    query = input().split()
    if query[0] == '1':
        u, v = int(query[1]), int(query[2])
        uf.union(u, v)
        edges[u].append(v)
        edges[v].append(u)
    elif query[0] == '2':
        u, v = int(query[1]), int(query[2])
        # Remove friendship
        # Find the component of u and v
        fu = uf.find(u)
        fv = uf.find(v)
        if fu == fv:
            # They are in the same component, we need to remove the edge
            # This is complex - let's just remove the edge from the adjacency list
            edges[u].remove(v)
            edges[v].remove(u)
    elif query[0] == '3':
        # Calculate answer
        # We need to simulate the process
        # Start with all nobles alive
        alive = [True] * (n + 1)
        for i in range(1, n + 1):
            alive[i] = True

        # While there are nobles with minimum power in their component
        while True:
            # Find all components
            components = {}
            for i in range(1, n + 1):
                if alive[i]:
                    root = uf.find(i)
                    if root not in components:
                        components[root] = []
                    components[root].append(i)

            # Check if any noble is vulnerable
            vulnerable = []
            for comp in components.values():
                min_power = min(uf.get_min(i) for i in comp)
                for i in comp:
                    if alive[i] and uf.get_min(i) == min_power:
                        vulnerable.append(i)

            if not vulnerable:
                break

            # Kill vulnerable nobles
            for i in vulnerable:
                alive[i] = False

        # Count remaining nobles
        count = sum(alive)
        print(count)
