import sys
import math

def mobius(n):
    """Compute the Möbius function for a number n"""
    if n == 1:
        return 1

    # Factorize n
    factors = set()
    for i in range(2, int(math.isqrt(n)) + 1):
        if n % i == 0:
            count = 0
            while n % i == 0:
                n //= i
                count += 1
            if count > 1:
                return 0  # Not square-free
            factors.add(i)

    if n > 1:
        factors.add(n)

    return -1 if len(factors) % 2 == 1 else 1

def comb(n, k, fact, inv_fact):
    """Compute combination C(n, k) modulo 10^9+7"""
    if k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

def solve():
    MOD = 10**9 + 7

    # Precompute factorials and inverse factorials up to 10^5
    max_n = 10**5
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact = [1] * (max_n + 1)
    inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
    for i in range(max_n, 0, -1):
        inv_fact[i-1] = inv_fact[i] * i % MOD

    # Read input
    data = sys.stdin.read().split()
    if not data:
        return

    q = int(data[0])
    idx = 1

    for _ in range(q):
        n = int(data[idx])
        f = int(data[idx+1])
        idx += 2

        # Find all divisors of n
        divisors = set()
        for i in range(1, int(math.isqrt(n)) + 1):
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)

        # Compute answer
        ans = 0
        for d in divisors:
            c = comb((n // d) - 1, f - 1, fact, inv_fact)
            mu = mobius(d)
            ans = (ans + mu * c) % MOD

        print(ans)

if __name__ == "__main__":
    solve()
