def is_k_beautiful(x, k):
    digits = set(str(x))
    return len(digits) <= k

def find_k_beautiful(n, k):
    s = str(n)
    length = len(s)

    # Try numbers with the same length
    for i in range(length):
        # Try to use one of the k allowed digits
        # We can use digits that appear in n if k is limited
        used_digits = set(str(n))

        # Try to change digit at position i
        for d in range(int(s[i]) + 1, 10):
            # Try to use digit d at position i
            # Check if we can use this digit without exceeding k different digits
            new_used = used_digits.copy()
            new_used.add(str(d))
            if len(new_used) <= k:
                # Try to fill the rest with the smallest possible digits
                new_num = s[:i] + str(d) + '0' * (length - i - 1)
                if int(new_num) >= n:
                    return int(new_num)

    # If no number with the same length works, try numbers with more digits
    return int('9' * (length + 1))

t = int(input())
for _ in range(t):
    n, k = map(int, input().split())
    print(find_k_beautiful(n, k))
